package ozl.environment.tests;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.lang.reflect.*;import zombie.ZomboidFileSystem;import zombie.modding.ActiveMods;
public final class LiveAgentProbe {
 static int checks;static void check(boolean ok,String s){checks++;if(!ok)throw new AssertionError(s);}static String read(Path p)throws Exception{return new String(Files.readAllBytes(p),StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{
  Path selected=Paths.get(args[0]),lua=Paths.get(args[1]),choices=Paths.get(args[2]),user=Paths.get(args[3]);ZomboidFileSystem fs=new ZomboidFileSystem();List<String> roots=new ArrayList<String>();fs.getAllModFolders(roots);
  boolean vanilla=Boolean.parseBoolean(args[4]),named=Boolean.parseBoolean(args[5]);check(roots.equals(vanilla?Collections.emptyList():Arrays.asList(lua.toString(),selected.toString())),"effective current root discovery");check(fs.liveScans==1,"live discovery still runs");check(fs.defaultText().equals(named?"mod=1299328280/ToadTraits\nmod=NamedB":"owned-default"),"owned default read");check(fs.loadedText().equals(Arrays.asList("owned-loaded")),"owned loaded read");ActiveMods.getById("default").source="owned-write";fs.saveModsFile();check(read(choices.resolve("mods/default.txt")).equals("owned-write")&&read(user.resolve("mods/default.txt")).equals("original-default"),"native save writes owned files only");check(fs.getCacheDir().equals(user.toString()),"cachedir stays real");
  ActiveMods active=new ActiveMods("save");active.getMods().addAll(Arrays.asList("1299328280/ToadTraits","Disabled"));check(active.getMods().equals(Arrays.asList("1299328280/ToadTraits","Disabled")),"save inspection getter remains pure");ActiveMods current=ActiveMods.getById("currentGame");current.copyFrom(active);fs.loadMods("currentGame");check(fs.loaded.equals(vanilla?Collections.emptyList():named?Arrays.asList("Viewpoint","1299328280/ToadTraits","NamedB"):Arrays.asList("Viewpoint","1299328280/ToadTraits"))&&ActiveMods.loaded.getMods().equals(fs.loaded),"current single-player selection and raw loaded bookkeeping agree");
  Path inspection=choices.resolve("inspection.txt");Files.write(inspection,"mod=One\nmod=Two\nmod=Three".getBytes(StandardCharsets.UTF_8));new zombie.modding.ActiveModsFile().read(inspection.toString(),active);check(active.getMods().equals(Arrays.asList("One","Two","Three")),"unscoped native parser retains every row without getter mutation");
  Path original=user.resolve("Saves/Sandbox/Original/mods.txt");Files.createDirectories(original.getParent());Files.write(original,"mod=One\nmod=Disabled\nmod=Two\nmod=Three".getBytes(StandardCharsets.UTF_8));new zombie.modding.ActiveModsFile().read(original.toString(),active);check(active.getMods().equals(vanilla?Collections.emptyList():named?Arrays.asList("Viewpoint","1299328280/ToadTraits","NamedB"):Arrays.asList("Viewpoint","One","Two","Three")),"completed trusted save read exposes effective selection to validation");current.copyFrom(active);current.source=vanilla?"":"mod=KeptAfterConfirmation";new zombie.modding.ActiveModsFile().write(original.toString(),current);check(read(original).equals("mod=One\nmod=Disabled\nmod=Two\nmod=Three")&&Files.list(choices.resolve("save-lists")).count()==1,"actual currentGame write reaches owned metadata path and leaves source bytes intact");
  new zombie.modding.ActiveModsFile().read(original.toString(),active);check(active.getMods().equals(vanilla?Collections.emptyList():Arrays.asList("Viewpoint","KeptAfterConfirmation")),"confirmation reread observes owned save selection without restoring original or named omissions");current.copyFrom(active);check(current.getMods().equals(active.getMods()),"confirmation copy preserves reread ordinary edits");
  zombie.network.GameClient.client=true;zombie.network.GameClient.instance.serverMods.addAll(Arrays.asList("ServerB","ServerA","Disabled"));fs.loadMods("client");check(fs.loaded.equals(vanilla?Arrays.asList("ServerB","ServerA","Disabled"):Arrays.asList("ServerB","ServerA","Disabled","Viewpoint")),"same menu JVM enters network phase with exact server order and only selected components appended");
  if(!vanilla){Files.write(lua.resolve("mod.info"),"id=Viewpoint\n".getBytes(StandardCharsets.UTF_8));fs.getAllModFolders(roots);check(roots.equals(Arrays.asList(selected.toString())),"current source update rediscovered");}
  System.out.println("PASS "+checks+" native live agent assertions");
 }
}
